import { PrismaClient } from "@prisma/client";
const db = new PrismaClient();
const [,, action, ...rest] = process.argv;
if (action === "move") {
  const [id, columnId] = rest;
  await db.card.update({ where:{ id }, data:{ columnId, position: 0 } });
  console.log("moved", id, "->", columnId);
} else if (action === "comment") {
  const [id, ...b] = rest;
  await db.cardComment.create({ data:{ cardId: id, authorName: "Claude", body: b.join(" ") } });
  console.log("commented on", id);
} else if (action === "count-blog") {
  console.log("published blog posts:", await db.blogPost.count({ where:{ published:true } }));
} else if (action === "find-done") {
  const cards = await db.card.findMany({ where:{ boardId:"cmsavdblr0008hla4pygic72o" }, select:{ id:true, title:true, columnId:true } });
  for (const c of cards) if (/backup/i.test(c.title)) console.log(JSON.stringify(c));
} else if (action === "card") {
  const c = await db.card.findUnique({ where:{ id: rest[0] }, include:{ attachments:true, comments:true } });
  console.log(JSON.stringify(c, null, 2));
}
await db.$disconnect();
EOF
node _board.mjs count-blog; echo "---"; node _board.mjs find-done

