{/* live footer — the row is ALWAYS rendered so it permanently reserves
    its height; only its visibility fades. Previously this collapsed
    (max-h-0) when not live, so every loop back to "live" grew the card
    and shoved the page content below it up/down — a constant vertical
    jump, very visible on mobile where sections stack. Keeping the space
    reserved holds the card at a fixed height across the whole loop. */}
<div
  className={`mt-4 overflow-hidden rounded-xl border transition-opacity duration-500 ${
    live ? "border-emerald-400/20 bg-emerald-400/[0.06] opacity-100" : "border-transparent opacity-0"
  }`}
  aria-hidden={!live}
>

