116	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
117	
118	  const rl = checkRateLimit(`files:upload:${user.id}`, { max: 30, windowMs: 60_000 });
119	  if (!rl.ok) {
120	    return NextResponse.json(
121	      { error: "too many uploads — slow down", retryAfterSec: rl.retryAfterSec },
122	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
123	    );
124	  }
125	
126	  const server = await ownedServer(serverId, user.id, user.role === "ADMIN");
127	  if (!server) return NextResponse.json({ error: "not found" }, { status: 404 });
128	
129	  let dir: string;
130	  try {
131	    dir = normalizePath(req.nextUrl.searchParams.get("path") ?? "");
132	  } catch (err) {
133	    return NextResponse.json(
134	      { error: err instanceof Error ? err.message : "invalid path" },
135	      { status: 400 }
136	    );
137	  }
138	
139	  let form: FormData;
140	  try {
141	    form = await req.formData();
142	  } catch {
143	    return NextResponse.json({ error: "expected a multipart upload" }, { status: 400 });
144	  }
145	
146	  const file = form.get("file");
147	  if (!(file instanceof File)) {
148	    return NextResponse.json({ error: "no file provided" }, { status: 400 });
149	  }
150	  if (file.size > MAX_UPLOAD_BYTES) {
151	    return NextResponse.json(
152	      { error: `file exceeds the ${MAX_UPLOAD_BYTES / (1024 * 1024)} MB upload limit` },
153	      { status: 413 }
154	    );
155	  }
156	
157	  let target: string;
158	  try {
159	    const name = validateName((file.name || "upload").trim());
160	    target = joinPath(dir, name);
161	  } catch (err) {
162	    return NextResponse.json(
163	      { error: err instanceof Error ? err.message : "invalid filename" },
164	      { status: 400 }
165	    );
166	  }
167	
168	  try {
169	    const data = Buffer.from(await file.arrayBuffer());
170	    // Re-check the actual byte length in case the reported size was understated.
171	    if (data.length > MAX_UPLOAD_BYTES) {
172	      return NextResponse.json({ error: "file too large" }, { status: 413 });
173	    }
174	    // Best-effort: create the destination directory. The file manager always
