export async function listBackups(vmid?: number): Promise<any[]> {
  const content = await pve.get(`/nodes/${NODE}/storage/backup/content`, { content: "backup" });
  return vmid ? content.filter((b: any) => b.vmid === vmid) : content;
}

/**
 * Absolute on-disk directory that the `backup` storage's vzdump archives live in
 * (customer on-demand backups). Proxmox has no HTTP endpoint that streams a
 * `.vma.zst` archive, so the customer download route (app/api/servers/
 * [serverId]/backups/download) reads the file off the host filesystem — the web
 * app runs on the Proxmox host. Resolution order: explicit env override, then the
 * `backup` storage's configured `path` + `/dump`, then the known default. Best
 * effort — never throws; falls back to the default on any error. */
export async function backupDumpDir(): Promise<string> {
  const override = process.env.NXEON_BACKUP_DUMP_DIR;
  if (override) return override;
  try {
    const cfg = await pve.get(`/storage/backup`);
    const base = typeof cfg?.path === "string" && cfg.path ? cfg.path : "/tank/backup";
    return `${base.replace(/\/+$/, "")}/dump`;
  } catch {
    return "/tank/backup/dump";
  }
}

